"""Pack cards: contracts/<pack>/README.md, generated by `contractctl cards`.

A card lists each contract of its pack with its "In short" and the rules it
marks MUST. Cards are derived data: they must match the contracts byte for
byte, they are never loaded as contracts, and a stale card is caught by
./tools/check-generated.sh with the command that fixes it.
"""

from __future__ import annotations

import re
import subprocess

from conftest import CT, REPO, _load_ct_from, run_py


def test_every_pack_has_a_current_card(lib):
    assert lib.stale_cards() == [], "run: contractctl cards --write"
    for pack in lib.LAYER_DIRS.values():
        assert (REPO / "contracts" / pack / lib.CARD_NAME).is_file()


def test_cards_are_not_contracts(lib):
    assert all(p.name != lib.CARD_NAME for p in lib.find_contract_files())


def test_card_lists_every_contract_in_its_pack(lib):
    contracts = lib.load_library()
    for card in lib.pack_cards(contracts):
        want = sorted(c["front_matter"]["contract_id"] for c in contracts
                      if c["front_matter"]["layer"] == card["pack"])
        assert sorted(e["id"] for e in card["contracts"]) == want
        if card["pack"] == "everyone":
            assert card["contracts"][0]["id"] == "floor"


def test_must_rules_match_the_markers_in_each_contract(lib):
    # the parser finds every (MUST) marker, and only those
    for c in lib.load_library():
        rules = lib.contract_rules(c["text"])
        section = lib.contract_section(c["text"], "Rules")
        assert sum(r["must"] for r in rules) == section.count("(MUST)"), c["rel_path"]
        assert len(rules) == len(re.findall(r"(?m)^\d+\.[ \t]", section)), c["rel_path"]
        assert all("(MUST)" not in r["text"] for r in rules)


def test_card_shows_must_rules_with_their_own_numbers(lib):
    card = next(c for c in lib.pack_cards() if c["pack"] == "work")
    bw = next(e for e in card["contracts"] if e["id"] == "bounded-work")
    assert bw["shown"] == "must"
    assert [r["number"] for r in bw["rules"]] == [1, 4, 6, 8]
    text = lib.render_card(card)
    assert "- **6.** Parallel lanes touch disjoint files." in text
    assert "[full text](BOUNDED_WORK.md)" in text


def test_unmarked_contracts_fall_back_to_headlines_or_full_text(lib):
    entries = {e["id"]: e for card in lib.pack_cards() for e in card["contracts"]}
    acc = entries["accessibility"]
    assert acc["shown"] == "headlines" and acc["rules"][0]["text"] == "Keyboard first-class."
    # floor rule 6's bold lead is not a whole sentence, so the floor shows full text
    floor = entries["floor"]
    assert floor["shown"] == "all"
    assert any("keep a way back" in r["text"] for r in floor["rules"])


def test_card_links_stay_inside_the_library(lib):
    for card in lib.pack_cards():
        folder = (REPO / card["path"]).parent
        for target in re.findall(r"\]\(([^)#\s]+)", lib.render_card(card)):
            assert (folder / target).exists(), (card["path"], target)


def test_cards_command_reports_then_repairs(library_git_copy, tmp_path):
    repo = library_git_copy(tmp_path / "lib")
    ct = repo / "tools" / "contractctl" / "contractctl.py"
    bw = repo / "contracts" / "work" / "BOUNDED_WORK.md"
    bw.write_text(bw.read_text().replace(
        "Every job has one goal, limits,", "Every job has one goal, firm limits,"))
    r = run_py(ct, ["cards"], cwd=repo)
    assert r.returncode == 1
    assert "contracts/work/README.md" in r.stdout
    assert "regenerate: contractctl cards --write" in r.stdout
    r = run_py(ct, ["cards", "--write"], cwd=repo)
    assert r.returncode == 0, r.stderr
    assert "one goal, firm limits" in (repo / "contracts/work/README.md").read_text()
    assert run_py(ct, ["cards"], cwd=repo).returncode == 0


def test_check_generated_names_a_stale_card(library_git_copy, tmp_path):
    repo = library_git_copy(tmp_path / "lib")
    card = repo / "contracts" / "people" / "README.md"
    card.write_text(card.read_text() + "\nhand edit\n")
    r = subprocess.run(["bash", str(repo / "tools" / "check-generated.sh")],
                       cwd=repo, capture_output=True, text=True, timeout=120)
    assert r.returncode == 1, r.stdout + r.stderr
    assert "STALE     pack cards" in r.stdout
    assert "contractctl.py cards --write" in r.stdout


def test_bump_refreshes_the_card(library_git_copy, tmp_path):
    repo = library_git_copy(tmp_path / "lib")
    ct = _load_ct_from(repo)
    path = repo / "contracts" / "work" / "OBSERVABILITY.md"
    path.write_text(path.read_text().replace("## In short\n\n", "## In short\n\nClearly: ", 1))
    _cid, done, errors = ct.bump_contract("observability", "patch", None)
    assert errors == [], errors
    assert any("contracts/work/README.md (pack card) refreshed" in d for d in done)
    assert "Clearly: " in (repo / "contracts/work/README.md").read_text()
    assert ct.stale_cards() == []


def test_cards_help_is_listed():
    r = run_py(CT, ["--help"])
    assert "cards" in r.stdout and "pack cards" in r.stdout
